def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    suspicious = []
    failed_attempts = {}

    for packet in packet_log:
        src_ip = packet.get("src_ip")
        status = packet.get("status")

        if status == "failed":
            failed_attempts[src_ip] = failed_attempts.get(src_ip, 0) + 1
            if failed_attempts[src_ip] >= 5:
                suspicious.append(packet)

        if packet.get("payload_size", 0) > 10000:
            suspicious.append(packet)

        if packet.get("dst_port") in {22, 3389, 445} and status == "blocked":
            suspicious.append(packet)

    return suspicious
