import os
import stat

def audit_file_permissions(directory: str) -> list[dict]:
    findings = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            if os.path.islink(path):
                continue
            try:
                st = os.stat(path)
                if st.st_mode & stat.S_IWOTH:
                    findings.append({
                        "file": path,
                        "permissions": oct(st.st_mode & 0o777),
                        "issue": "world-writable"
                    })
            except OSError:
                pass
    return findings
```

